package com.optarena.app

object Scaler {
    // Return each element doubled, in order.
    // BUG: `acc = acc + (x * 2)` rebuilds the whole immutable list every
    // iteration -> O(n^2), far too slow for large inputs.
    fun doubleEach(xs: List<Int>): List<Int> {
        var acc = emptyList<Int>()
        for (x in xs) {
            acc = acc + (x * 2)
        }
        return acc
    }
}

