package com.optarena.app

import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Assertions.assertTrue
import org.junit.jupiter.api.Test

class ScalerTest {

    @Test
    fun doublesInOrder() {
        assertEquals(listOf(2, 4, 6), Scaler.doubleEach(listOf(1, 2, 3)))
    }

    @Test
    fun emptyStaysEmpty() {
        assertEquals(emptyList<Int>(), Scaler.doubleEach(emptyList()))
    }

    @Test
    fun performanceLargeInput() {
        val xs = (0 until 100_000).toList()
        val expected = xs.map { it * 2 }

        val start = System.nanoTime()
        val got = Scaler.doubleEach(xs)
        val elapsed = (System.nanoTime() - start) / 1e9

        assertEquals(expected, got)
        assertTrue(
            elapsed < 1.0,
            "doubleEach took ${elapsed}s for 100000 elements; expected an O(n) " +
                "accumulation, not rebuilding an immutable list with + each iteration"
        )
    }
}

